const cached = $json.inv_cached;
try {
  const parsed = typeof cached === 'string' ? JSON.parse(cached) : cached;
  return [{ json: { ...parsed, _from_cache: true } }];
} catch (e) {
  return [{ json: { ok: false, _from_cache: false, _parse_error: e.message } }];
}

function F(rec){ return (rec && rec.fields && typeof rec.fields==='object') ? rec.fields : (rec||{}); }
function norm(s){return String(s==null?'':s).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\bBAJAJ\b/g,' ').replace(/[^A-Z0-9]+/g,' ').trim();}
function toks(s){return norm(s).split(' ').filter(Boolean);}
var CC_LIST=[100,110,125,150,160,180,200,220,250,400];
function extractCC(s){
  var t=norm(s);
  var nums=(t.match(/\d{3}/g)||[]).map(Number);
  for(var i=0;i<nums.length;i++){ if(CC_LIST.indexOf(nums[i])>=0) return nums[i]; }
  var z=t.match(/(\d{3})Z/); if(z && CC_LIST.indexOf(Number(z[1]))>=0) return Number(z[1]);
  return null;
}
function extractVariant(s){
  var t=' '+norm(s)+' ';
  if(/\bNS\d{2,3}\b/.test(t) || /\bNS\b/.test(t)) return 'NS';
  if(/\bN\d{2,3}\b/.test(t) || /\bN\b/.test(t))  return 'N';
  if(/\bF\d{2,3}\b/.test(t) || /\bF\b/.test(t))  return 'F';
  if(/\bRS\d{2,3}\b/.test(t) || /\bRS\b/.test(t)) return 'RS';
  return '';
}
function familyOf(s){ var tk=toks(s); return tk.length?tk[0]:''; }

const input = $('When Executed by Another Workflow').first().json.modelo || '';
const models = $input.all().map(i=>i.json).filter(m=>m && m.id);
const inNorm = norm(input);
const inCC = extractCC(input);
const inVar = extractVariant(input);
const inFam = familyOf(input);
const inSet = new Set(toks(input));

function score(name){
  if(norm(name) === inNorm) return 1000;
  const cc=extractCC(name), va=extractVariant(name), fam=familyOf(name);
  let s=0;
  if(inFam && fam===inFam) s+=40;
  if(inCC && cc===inCC) s+=40;
  if(inVar && va===inVar) s+=25;
  const nset=new Set(toks(name));
  for(const t of inSet){ if(nset.has(t)) s+=3; }
  return s;
}

// Score all models
const scored = models.map(m => {
  const f = F(m);
  const nombre = f.nombre || '';
  return { model: m, nombre, score: score(nombre), f };
}).filter(x => x.score >= 40).sort((a,b) => b.score - a.score);

// Dedup by name (same model in 2025 + 2026)
const seen = {};
const unique = [];
for(const s of scored){
  if(!seen[s.nombre]){ seen[s.nombre]=true; unique.push(s); }
}

// ── Exact match (score 1000) ──
if(unique.length > 0 && unique[0].score === 1000){
  const f = unique[0].f; const cn = f.nombre || '';
  return [{ json: {
    matched:true, ambiguous:false, match_type:'exacto',
    modelo:cn, precio:(f.precio??null), categoria:(f.categoria??null),
    cilindrada_cc:(f.cilindrada_cc??extractCC(cn)),
    familia:familyOf(cn), cc:extractCC(cn), variante:extractVariant(cn),
    _diag_models:models.length
  }}];
}

// ── Ambiguity check: multiple models tied within 10 pts ──
if(unique.length > 1){
  const topScore = unique[0].score;
  const tied = unique.filter(x => x.score >= topScore - 10);
  if(tied.length > 1){
    const candidates = tied.map(x => ({
      nombre: x.nombre,
      precio: x.f.precio ?? null,
      precio_formato: x.f.precio != null ? '$'+Number(x.f.precio).toLocaleString('en-US') : null,
      categoria: x.f.categoria ?? null,
      cilindrada_cc: x.f.cilindrada_cc ?? extractCC(x.nombre),
      descripcion: x.f.descripcion ?? ''
    }));
    return [{ json: {
      matched:false, ambiguous:true, match_type:'ambiguo',
      modelo:input, candidates,
      familia:inFam, cc:inCC, variante:inVar,
      cilindrada_cc:inCC, precio:null, categoria:null,
      _diag_models:models.length
    }}];
  }
}

// ── Single best match ──
if(unique.length > 0){
  const f = unique[0].f; const cn = f.nombre || '';
  return [{ json: {
    matched:true, ambiguous:false, match_type:'parcial',
    modelo:cn, precio:(f.precio??null), categoria:(f.categoria??null),
    cilindrada_cc:(f.cilindrada_cc??extractCC(cn)),
    familia:familyOf(cn), cc:extractCC(cn), variante:extractVariant(cn),
    _diag_models:models.length
  }}];
}

// ── No match ──
return [{ json: {
  matched:false, ambiguous:false, match_type:'sin_match',
  modelo:input, precio:null, categoria:null,
  cilindrada_cc:inCC, familia:inFam, cc:inCC, variante:inVar,
  _diag_models:models.length
}}];

function F(rec){ return (rec && rec.fields && typeof rec.fields==='object') ? rec.fields : (rec||{}); }
function norm(s){return String(s==null?'':s).toUpperCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\bBAJAJ\b/g,' ').replace(/[^A-Z0-9]+/g,' ').trim();}
function toks(s){return norm(s).split(' ').filter(Boolean);}
