function extractCC(s){
  var t=norm(s); var nums=(t.match(/\d{3}/g)||[]).map(Number);
  for(var i=0;i<nums.length;i++){ if(CC_LIST.indexOf(nums[i])>=0) return nums[i]; }
  var z=t.match(/(\d{3})Z/); if(z && CC_LIST.indexOf(Number(z[1]))>=0) return Number(z[1]);
  return null;
}
function extractVariant(s){
  var t=' '+norm(s)+' ';
  if(/\bNS\d{2,3}\b/.test(t) || /\bNS\b/.test(t)) return 'NS';
  if(/\bN\d{2,3}\b/.test(t) || /\bN\b/.test(t))  return 'N';
  if(/\bF\d{2,3}\b/.test(t) || /\bF\b/.test(t))  return 'F';
  if(/\bRS\d{2,3}\b/.test(t) || /\bRS\b/.test(t)) return 'RS';
  return '';
}
function familyOf(s){ var tk=toks(s); return tk.length?tk[0]:''; }

const trig = $('When Executed by Another Workflow').first().json;
const r = $('Code · Resolve Model').first().json;

// ═══ AMBIGUO: devolver candidatos sin inventario detallado ═══
if(r.ambiguous === true){
  const nombres = (r.candidates||[]).map(c => c.nombre);
  return [{ json: {
    ok: true,
    match_type: 'ambiguo',
    modelo_buscado: r.modelo,
    candidatos: r.candidates,
    num_candidatos: nombres.length,
    mensaje_agente: 'No encontré un modelo exacto llamado "' + r.modelo + '". Hay '
      + nombres.length + ' opciones: ' + nombres.join(', ')
      + '. Pregúntale al cliente cuál le interesa para darte la disponibilidad exacta.',
    disponibles: null, por_sucursal: [], situacion: 'ambiguo',
    precio: null, precio_formato: null, cilindrada_cc: r.cilindrada_cc,
    categoria: null, baja_disponibilidad: false,
    _from_cache: false, _diag: { modelos: r._diag_models }
  }}];
}

// ═══ FLUJO NORMAL (exacto o parcial) ═══
const tCC = r.cc, tVar = r.variante, tFam = r.familia;

let invRows=[]; try{ invRows = $('Airtable · Get Inventory by Family').all().map(i=>i.json).filter(x=>x && x.id); }catch(e){}
let branches=[]; try{ branches = $('Airtable · Get All Branches').all().map(i=>F(i.json)).filter(b=>b.sucursal_id); }catch(e){}
const branchById={}; for(const b of branches){ branchById[String(b.sucursal_id)] = b; }

function rowMatches(f){
  const fam=familyOf(f.familia_modelo||f.nombre_modelo);
  const cc=extractCC(f.nombre_modelo);
  const va=extractVariant(f.nombre_modelo);
  if(tFam && fam!==tFam) return false;
  if(tCC && cc!==tCC) return false;
  if(tVar && va!==tVar) return false;
  return true;
}

const groups={}; let disponibles=0;
for(const row of invRows){
  const f=F(row); if(!rowMatches(f)) continue;
  const c=Number(f.cantidad); const u=(!isNaN(c)&&c>0)?c:1; disponibles+=u;
  const sid=String(f.sucursal_id||'');
  const b=branchById[sid];
  const key= sid || ('I:'+(f.sucursal_nombre||'?'));
  if(!groups[key]){
    groups[key]= b ? { sucursal_id:b.sucursal_id, sucursal_nombre:(b.nombre||f.sucursal_nombre||''), ciudad:(b.ciudad||''),
                       direccion:(b.direccion||''), google_maps:(b.google_maps||''), horario:(b.horario||''), unidades:0, resuelta:true }
                   : { sucursal_id:(f.sucursal_id||null), sucursal_nombre:(f.sucursal_nombre||''), ciudad:'', unidades:0, resuelta:false };
  }
  groups[key].unidades += u;
}
const por_sucursal = Object.values(groups).sort((a,b)=>b.unidades-a.unidades);

const precio = (r.precio===''?null:(r.precio??null));
let situacion='disponible'; if(disponibles===0) situacion='agotado'; else if(disponibles<=3) situacion='pocas';
const ok = (r.matched===true) || disponibles>0;
const result={ ok, match_type:(r.match_type||'parcial'),
  modelo:(r.modelo||trig.modelo), disponibles, por_sucursal, num_sucursales_con_stock:por_sucursal.length,
  precio, precio_formato:(precio!=null?'$'+Number(precio).toLocaleString('en-US'):null),
  cilindrada_cc:(r.cilindrada_cc??null), categoria:(r.categoria??null),
  baja_disponibilidad:(disponibles>0 && disponibles<=3), situacion,
  _diag:{ modelos:(r._diag_models??null), inv_familia:invRows.length, sucursales:branches.length }, _from_cache:false };
if(!ok) result.error='modelo_no_encontrado';
return [{ json: result }];
